// Exchanges the two ints that a and b point at.
void swapValues(int* a, int* b)
{
    const int kept{ *a };   // remember the first value before it is overwritten
    *a = *b;
    *b = kept;
}

unitTests:
TEST("two different values") {
    int x{ 3 }, y{ 9 };
    swapValues(&x, &y);
    CHECK_EQ(x, 9);
    CHECK_EQ(y, 3);
}
TEST("negative numbers and zero") {
    int x{ -40 }, y{ 0 };
    swapValues(&x, &y);
    CHECK_EQ(x, 0);
    CHECK_EQ(y, -40);
}
TEST("two elements of an array") {
    int values[4]{ 10, 20, 30, 40 };
    swapValues(&values[0], &values[3]);
    CHECK_EQ(values[0], 40);
    CHECK_EQ(values[3], 10);
    CHECK_EQ(values[1], 20);
}
TEST("a variable swapped with itself keeps its value") {
    int x{ 7 };
    swapValues(&x, &x);
    CHECK_EQ(x, 7);
}

